1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 8px;
43	  }
44	  button {
45	    height: 56px;
46	    border: 0;
47	    border-radius: 10px;
48	    background: #3a3f47;
49	    color: #fff;
50	    font-size: 22px;
51	    cursor: pointer;
52	  }
53	  button:active { filter: brightness(1.3); }
54	  button.op { background: #f0a030; }
55	  button.clear { background: #a5a5a5; color: #111; }
56	  button.equals { background: #3c8cf0; }
57	  button.wide { grid-column: span 2; }
58	  .tape {
59	    margin-top: 12px;
60	    padding: 8px 12px;
61	    background: #111418;
62	    border-radius: 10px;
63	    color: #fff;
64	  }
65	  .tape-head {
66	    display: flex;
67	    align-items: center;
68	    justify-content: space-between;
69	    font-size: 13px;
70	    color: #9aa0a8;
71	  }
72	  .tape-head button {
73	    height: auto;
74	    padding: 4px 10px;
75	    font-size: 13px;
76	    background: #3a3f47;
77	  }
78	  .tape-rows { max-height: 160px; overflow-y: auto; }
79	  .tape-row {
80	    padding: 6px 0;
81	    border-top: 1px solid #2a2f36;
82	    text-align: right;
83	    overflow-wrap: anywhere;
84	  }
85	  .tape-row:first-child { border-top: 0; }
86	  .tape-expr { font-size: 13px; color: #9aa0a8; }
87	  .tape-result { font-size: 18px; }
88	</style>
89	</head>
90	<body>
91	<div class="calc">
92	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
93	  <div class="keys">
94	    <button class="clear wide" data-testid="key-lparen" aria-label="open group">(</button>
95	    <button class="clear wide" data-testid="key-rparen" aria-label="close group">)</button>
96	
97	    <button class="clear wide" data-testid="key-clear">AC</button>
98	    <button class="clear" data-testid="key-sign" aria-label="change sign">±</button>
99	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
100	
101	    <button data-testid="key-7">7</button>
102	    <button data-testid="key-8">8</button>
103	    <button data-testid="key-9">9</button>
104	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
105	
106	    <button data-testid="key-4">4</button>
107	    <button data-testid="key-5">5</button>
108	    <button data-testid="key-6">6</button>
109	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
110	
111	    <button data-testid="key-1">1</button>
112	    <button data-testid="key-2">2</button>
113	    <button data-testid="key-3">3</button>
114	    <button class="op" data-testid="key-add" aria-label="add">+</button>
115	
116	    <button class="wide" data-testid="key-0">0</button>
117	    <button data-testid="key-dot" aria-label="decimal point">.</button>
118	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
119	  </div>
120	  <div class="tape">
121	    <div class="tape-head">
122	      <span>History</span>
123	      <button data-testid="tape-clear">Clear</button>
124	    </div>
125	    <div class="tape-rows" data-testid="calc-tape" aria-label="past calculations"></div>
126	  </div>
127	</div>
128	<script>
129	(function () {
130	  var display = document.querySelector('[data-testid="calc-display"]');
131	  var tape = document.querySelector('[data-testid="calc-tape"]');
132	
133	  // entry: string being typed, or null when no entry is in progress.
134	  // value: the number currently shown when not typing (result or stored operand).
135	  // derived: true when entry came from ± on a computed number rather than typing;
136	  // it is shown formatted, and the next digit starts a new entry.
137	
138	  // groups: stack of the outer { stored, op, expr } saved by each open "(".
139	  // expr: tokens of the expression written so far at the current group level.
140	  // entryExpr: how the entry reads in the expression when it is a closed group.
141	  var state;
142	
143	  var opSymbols = { add: '+', sub: '−', mul: '×', div: '÷' };
144	
145	  // [REQ-001] [REQ-004] [REQ-005] [REQ-007]
146	  function reset() {
147	    state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false, groups: [],
148	      expr: [], entryExpr: null };
149	  }
150	
151	  // [REQ-007]
152	  // How the current operand reads in the tape expression.
153	  function operandText() {
154	    if (state.entry === null) return formatNumber(state.value);
155	    if (state.entryExpr !== null) return state.entryExpr;
156	    if (state.derived) return formatNumber(Number(state.entry));
157	    return state.entry.replace(/\.$/, '');
158	  }
159	
160	  // [REQ-007]
161	  // Newest row first. The tape is not part of state, so AC keeps it.
162	  function addTapeRow(expr, result) {
163	    var row = document.createElement('div');
164	    row.className = 'tape-row';
165	    row.setAttribute('data-testid', 'tape-row');
166	    var e = document.createElement('div');
167	    e.className = 'tape-expr';
168	    e.setAttribute('data-testid', 'tape-expr');
169	    e.textContent = expr;
170	    var r = document.createElement('div');
171	    r.className = 'tape-result';
172	    r.setAttribute('data-testid', 'tape-result');
173	    r.setAttribute('data-value', String(result));
174	    r.textContent = formatNumber(result);
175	    row.appendChild(e);
176	    row.appendChild(r);
177	    tape.insertBefore(row, tape.firstChild);
178	  }
179	
180	  // [REQ-001]
181	  function compute(a, op, b) {
182	    var r;
183	    if (op === 'add') r = a + b;
184	    else if (op === 'sub') r = a - b;
185	    else if (op === 'mul') r = a * b;
186	    else if (op === 'div') r = a / b;
187	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
188	    // The result is never rounded here: rounding is presentation only.
189	    if (!isFinite(r)) return NaN;
190	    return r;
191	  }
192	
193	  // [REQ-003]
194	  // Presentation only: at most 10 significant digits, no trailing zeros, no
195	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
196	  function formatNumber(n) {
197	    if (n === 0) return '0';
198	    var r = Number(n.toPrecision(10));
199	    var abs = Math.abs(r);
200	    if (abs >= 1e10 || abs < 1e-9) {
201	      return r.toExponential(9).replace(/\.?0+e/, 'e');
202	    }
203	    var exp = parseInt(r.toExponential().split('e')[1], 10);
204	    var s = r.toFixed(Math.max(0, 9 - exp));
205	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
206	  }
207	
208	  // [REQ-001] [REQ-003]
209	  function render() {
210	    display.setAttribute('data-error', state.error ? 'true' : 'false');
211	    if (state.error) {
212	      display.textContent = 'Error';
213	      display.setAttribute('data-value', String(NaN));
214	      return;
215	    }
216	    if (state.entry !== null) {
217	      display.textContent = state.derived ? formatNumber(Number(state.entry)) : state.entry;
218	      display.setAttribute('data-value', String(Number(state.entry)));
219	    } else {
220	      display.textContent = formatNumber(state.value);
221	      display.setAttribute('data-value', String(state.value));
222	    }
223	  }
224	
225	  // [REQ-001] [REQ-007]
226	  function inputDigit(d) {
227	    if (state.derived) { state.entry = null; state.derived = false; state.entryExpr = null; }
228	    if (state.entry === null || state.entry === '0') state.entry = d;
229	    else state.entry += d;
230	  }
231	
232	  // [REQ-001] [REQ-007]
233	  function inputDot() {
234	    if (state.derived) { state.entry = null; state.derived = false; state.entryExpr = null; }
235	    if (state.entry === null) state.entry = '0.';
236	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
237	  }
238	
239	  // [REQ-004] [REQ-006] [REQ-007]
240	  // ± acts on the current entry. With no entry in progress, the number on
241	  // the display becomes the entry, so it can still feed the pending operation.
242	  function inputSign() {
243	    if (state.entry === null) { state.entry = String(state.value); state.derived = true; }
244	    state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
245	    if (state.entryExpr !== null) {
246	      state.entryExpr = state.entryExpr.charAt(0) === '-' ? state.entryExpr.slice(1) : '-' + state.entryExpr;
247	    }
248	  }
249	
250	  // [REQ-001] [REQ-002] [REQ-007]
251	  // Immediate execution: an operator key first finishes the waiting operation,
252	  // strictly left to right, with no precedence, so the display always shows a
253	  // real running result. 2 + 3 × 4 = 20.
254	  function inputOperator(op) {
255	    if (state.error) return;
256	    if (state.entry === null && state.expr.length > 0) {
257	      // A second operator in a row replaces the first.
258	      state.expr[state.expr.length - 1] = opSymbols[op];
259	    } else {
260	      state.expr.push(operandText(), opSymbols[op]);
261	    }
262	    if (state.entry !== null) {
263	      var n = Number(state.entry);
264	      state.entry = null;
265	      state.derived = false;
266	      state.entryExpr = null;
267	      if (state.op !== null && state.stored !== null) {
268	        state.value = compute(state.stored, state.op, n);
269	        if (isNaN(state.value)) { state.error = true; return; }
270	      } else {
271	        state.value = n;
272	      }
273	    }
274	    state.stored = state.value;
275	    state.op = op;
276	  }
277	
278	  // [REQ-005] [REQ-007]
279	  // "(" starts a group only where a new number could start. It saves the waiting
280	  // operation and begins a fresh calculation inside the group.
281	  function inputOpenGroup() {
282	    if (state.entry !== null) return;
283	    state.groups.push({ stored: state.stored, op: state.op, expr: state.expr });
284	    state.stored = null;
285	    state.op = null;
286	    state.expr = [];
287	  }
288	
289	  // [REQ-005] [REQ-007]
290	  // ")" finishes the calculation inside the group, left to right, and hands its
291	  // result back as the entry for the saved outer operation.
292	  function inputCloseGroup() {
293	    if (state.groups.length === 0 || state.entry === null) return;
294	    var n = Number(state.entry);
295	    if (state.op !== null && state.stored !== null) {
296	      n = compute(state.stored, state.op, n);
297	      if (isNaN(n)) { state.error = true; return; }
298	    }
299	    var inner = state.expr.concat(operandText()).join(' ');
300	    var outer = state.groups.pop();
301	    state.stored = outer.stored;
302	    state.op = outer.op;
303	    state.expr = outer.expr;
304	    state.value = n;
305	    state.entry = String(n);
306	    state.derived = true;
307	    state.entryExpr = '(' + inner + ')';
308	  }
309	
310	  // [REQ-001] [REQ-005] [REQ-007]
311	  function inputEquals() {
312	    // Groups still open are closed first.
313	    while (!state.error && state.groups.length > 0 && state.entry !== null) inputCloseGroup();
314	    if (state.error || state.op === null || state.entry === null) return;
315	    var result = compute(state.stored, state.op, Number(state.entry));
316	    var expr = state.expr.concat(operandText()).join(' ');
317	    state.entry = null;
318	    state.derived = false;
319	    state.entryExpr = null;
320	    state.expr = [];
321	    state.op = null;
322	    state.stored = null;
323	    if (isNaN(result)) { state.error = true; return; }
324	    state.value = result;
325	    addTapeRow(expr, result);
326	  }
327	
328	  // [REQ-001] [REQ-003] [REQ-004] [REQ-005] [REQ-006] The % key was removed.
329	  function press(key) {
330	    // In the error state every key except clear is ignored.
331	    if (state.error && key !== 'clear') return;
332	    if (/^[0-9]$/.test(key)) inputDigit(key);
333	    else if (key === 'dot') inputDot();
334	    else if (key === 'sign') inputSign();
335	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
336	    else if (key === 'lparen') inputOpenGroup();
337	    else if (key === 'rparen') inputCloseGroup();
338	    else if (key === 'equals') inputEquals();
339	    else if (key === 'clear') reset();
340	    render();
341	  }
342	
343	  document.querySelector('.keys').addEventListener('click', function (e) {
344	    var btn = e.target.closest('button[data-testid^="key-"]');
345	    if (btn) press(btn.getAttribute('data-testid').slice(4));
346	  });
347	
348	  // [REQ-007] Empties the tape only; the display and calculation are untouched.
349	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
350	    tape.textContent = '';
351	  });
352	
353	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
354	    '/': 'div', '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
355	  document.addEventListener('keydown', function (e) {
356	    if (e.metaKey || e.ctrlKey || e.altKey) return;
357	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
358	    if (key) {
359	      e.preventDefault();
360	      press(key);
361	    }
362	  });
363	
364	  reset();
365	  render();
366	})();
367	</script>
368	</body>
369	</html>
